import collections

def find_inversions(seq):
    """Count inversions in a sequence."""
    stack = []
    inversions = 0
    for i, char in enumerate(seq):
        while stack and char < stack[-1][0]:
            inx, char_to_remove = stack.pop()
            inversions += i - inx
        stack.append([char, i])
    return inversions

def generate_combinations(s):
    """Generate all combinations of string subsequence using LinkedList notation."""
    result = []
    stack = collections.deque([s[0]])
    for i in range(1, len(s)):
        for j in range(i, len(s)):
            binary = s[j]
            while stack and binary < stack[-1][0]:
                idx, char = stack.pop()
                if binary < char:
                    return result
            stack.append((binary, len(binary)))
    return result

