def update_tree(tree, left, right, update_value, node):
    if left == right:
        tree[node][0] %= n
        tree[node][1] %= n
        tree[node][2] %= n
    elif left > right:
        return
    update_value %= n
    if update_value <= right - left + 1:
        tree[node][0] = update_value % n
    else:
        update_tree(tree, left, ((left + right) >> 1), update_value, node * 2)
        update_tree(tree, ((left + right) >> 1) + 1, right, update_value, node * 2 + 1)
        tree[node][0] = (tree[node * 2][0] + tree[node * 2 + 1][0]) % n
        tree[node][1] = (tree[node * 2][1] + tree[node * 2 + 1][1]) % n
