import sys

def solve(n, r, c, portals):
    m = 0
    seen = set()
    for ri, ci in zip(r, c):
        for i in range(1, ri):
            if (i, ci) in seen:
                break
            seen.add((i, ci))
        else:
            m += 1
            yield r, 1, ri, ci
            break
    else:
        for i in range(1, c[0] - 1):
            if (n, i) in seen:
                break
            seen.add((n, i))
        else:
            m += 1
            yield n, ci - 1, n, c[-1]

        for i in range(c[-1] + 1, 1, -1):
            if (i, n) in seen:
                break
            seen.add((i, n))
        else:
            m += 1
            yield i, n, ci, n

            submap = [[] for _ in range(n)]
            for x in range(n):
                submap[x] = [r[x] for r in portals]
            submap[n // 2] = []
