def dp(max_depth, k):
    max_diff = {0: 1}
    for diff in range(max_depth, -1, -1):
        curr_max = 1
        for h in range(k, max_depth - diff + 2):
            # Add this to the previous vertex
            old_max = max_diff[h - k - 1]
            # Subtract the maximum difference
            new_diff = (max_depth - h) + 1 + min(diff, k + h - diff)
            max_diff[h] = min(old_max, curr_max) + old_max - max(max_diff[h - k - 1], old_max) + max_diff[h - k - 1]
            curr_max = max(curr_max, max_diff[h] + old_max - max_diff[h - k - 1])
    return curr_max

