class StringAlgorithm:
    def __init__(self, s):
        self.s = s
        self.ans = []

    def apply_algorithm(self):
        for i in range(len(self.s)):
            self.ans.append(f"{len(self.remove_edges(i))}{self.remove_edges(i)}")

