import sys

def max_leave_visits(n, k):
    if n == 1:
        return 0
    if k == 0:
        return 1

    leaves = [i for i in range(n) if i == 1 or all(p != i for p in range(1, i))]
    if len(leaves) <= k:
        return len(leaves)

    max_visits = len(leaves[0:k])

    for i, v in enumerate(leaves):
        if i < k:
            continue
        v_leaves = len(leaves[i - k:i])
        max_visits = max(max_visits, v_leaves + i - k)

    return max_visits

