@lru_cache(maxsize=None)
def count_impl(s: str, t: str, n: int, acc: str = '') -> int:
    if n == 0:
        return acc == s
    total = 0
    for i in range(1, len(s)+1):
        if is_symmetric(s[:i]):
            total += count_impl(s[i:], t, n-1, acc + s[0:i])
    return total

