class SegmentTree:
    def __init__(self, n):
        self.n = n
        self.tree = [0] * (4 * n)
        self.size = 0

    def update(self, node, val):
        self.tree[self.size] = val
        node += self.size
        self.size += 1
        while node > 1:
            self.tree[node >> 1] = (self.tree[node] + self.tree[node ^ 1]) % mod
            node >>= 1

    def query(self, start, end, node, left, right):
        if start > end or start > right or end < left:
            return 0
        if start <= left and right <= end:
            return self.tree[node]
        mid = left + (right - left) // 2
        return (self.query(start, end, node * 2, left, mid) + self.query(start, end, node * 2 + 1, mid + 1, right)) % mod

def solve(params):
