from typing import List
import itertools

def solve(points: List[List[int]], string: str):
    n = len(points)
    left_turns = []
    edge_availability = [True] * n

    for i in range(n-1):
        if string[i] == 'L':
            edge_availability[i+1] = False
        else:
            edge_availability[i] = False

    for _ in range(2):
        for order, edge in itertools.product(range(n), edge_availability):
            if edge:
                points[order][0], points[order][1] = points[order][1], points[order][0]

    for (x1, y1), (x2, y2), (x3, y3) in itertools.combinations(points, 3):
        if (y2 - y1) * (x3 - x2) == (y3 - y2) * (x2 - x1):
            return -1

    for i in range(n):
        for j in range(i+1, n):
            if points[i][1] > points[j][1]:
                points[i], points[j] = points[j], points[i]

    return "".join(map(str, points))

