        dp_size = dp_szn

    # process the reverse case
    if 0 < start:
        if start < dp_size - 1 and s == dp_s[start]:
            dp_s[start + 1] = dp_s[start + 1] - 1
            return dp_szn + 1

    if dp_s[(dp_szn + dp_size - 1) % dp_size] < dp_s[(dp_szn - 1) % dp_size]:
        dp_s[(dp_szn - 1) % dp_size] = dp_s[(dp_szn - 1) % dp_size] + 1
        return dp_szn + 1

    # process the merge case
    if start + 1 < dp_size - 1 and dp_s[(dp_szn + 1) % dp_size] == dp_s[(dp_szn - 1) % dp_size] and dp_s[(dp_szn + 1) % dp_size + 1] - dp_s[(dp_szn - 1) % dp_size - 1] == dp_s[(dp_szn - 1) % dp_size]:
        dp_s[(dp_szn + 1) % dp_size] = dp_s[(dp_szn + 1) % dp_size] + 1
        dp_s[(dp_szn - 1) % dp_size - 1] = dp_s[(dp_szn - 1) % dp_size - 1] + 1

