    return _find_winding_order(s1, 2 * n)

def _find_winding_order(points, n):
    current_angle = math.degrees(math.atan2(points[0][0], points[0][1]))
    ans = [(i + 1, current_angle) for i in range(n // 2)]
    for i in range(n // 2):
        p = (points[i][0] - points[i + 1][0], points[i][1] - points[i + 1][1])
        p = rotate_point(p, ans[i][1])
        current_angle = math.degrees(math.atan2(p[1], p[0]))
        ans[i + n // 2] = (ans[i][1] + (n + i) % n, current_angle)
    return ans
