def count_ways(n, max_tries):
    ways = 0
    if n == 1:
        return 1
    elif n == 2:
        return 1
    else:
        for i in range(2, n + 1):
            left_ways = count_ways(i - 1, max_tries[i])
            middle_ways = i * (i - 1) // 2
            right_ways = max_tries[n - i]
            total = left_ways * middle_ways * right_ways
            ways += total
            ways %= 1000000007
    return ways

def main():
    n = int(input())
    max_tries = list(map(int, input().split()))
    print(count_ways(n, max_tries))

