def is_wavy(number):
    s = str(number)
    if len(s) < 3:
        return False
    for i in range(1, len(s) - 1):
        if int(s[i]) in (0, 9):
            return False
        if (s[i - 1] in (0, 9) and int(s[i] > 1)) or (s[i + 1] in (0, 9) and int(s[i] > 1)):
            return True
        if (s[i - 1] in (0, 9) and int(s[i] < 9)) or (s[i + 1] in (0, 9) and int(s[i] < 9)):
            return True
    return False

def find_kth_smallest(n, k):
    count = 0
    num = 0
    while count < k and num <= 10**14:
        num = (n * (10**13)) % count
        if num == 0 and count in (2, 3):
            return -1
        largest = 0
        for i in range(1, 10):
            newnum = (num * 10 + i) * 10 ** 13
            if is_wavy(newnum):
                newnum += 1
                while newnum < 10**14 and newnum % n == 0 and not is_wavy(newnum):
                    newnum += 1
                if newnum < 10**14 and newnum % n == 0:
                    largest = max(largest, newnum)
        count += 1
    return largest

