from itertools import permutations, chain, product

def is_palindrome(s):
    return s == s[::-1]

def get_unique_decorations(T, N):
    unique_decorations = []

    for perm in permutations(T):
        for i in range(N):
            for j in range(N):
                if is_palindrome(''.join(chain(perm[i:], perm[j:], tuple(perm[f - (i - j)] for f in range(N) if f not in (i, j))))):
                    unique_decorations.append(''.join(chain(perm[i:], perm[j:])))

    return list(set(unique_decorations))

