from collections import defaultdict

def max_visits(n, k, parents):
    children = defaultdict(list)
    for i, parent in enumerate(parents, start=1):
        children[parent].append(i)

    leaves = []
    for i in range(1, n+1):
        if len(children[i]) == 0:
            leaves.append(i)

    while len(leaves) > 1 and k > 0:
        new_leaves = []
        for i in leaves:
            for child in children[i]:
                if child not in new_leaves and len(children[child]) > 0:
                    new_leaves.append(child)
                    k -= 1
        leaves = new_leaves

    return len(leaves)

