from math import pow

def find_kth_wavy_number(n, k):
    if n > 10**14 or k > 10**14:
        return -1

    def is_wavy(num):
        prev = num % 10
        cur = 0
        for digit in num:
            cur = int(digit)
            if prev <= cur or prev >= cur:
                return False
            prev = cur
        return True

    l, r = 1, 10**14
    while l < r:
        mid = (l + r) // 2
        if is_wavy(mid) and n * mid < k * pow(10, 9):
            l = mid + 1
        else:
            r = mid

    r = k * pow(10, 9) * (n * is_wavy(r) < n)
    print(r) if r < 10**14 else "100000"

