from collections import defaultdict, deque

def paint_monster_map(k, n, start_positions, monster_positions, stones):
    prev_stone = stones[-1]

    stones_with_remaining_uses = []
    stones_used = set([prev_stone])

    for stone in stones:
        if stone[0] > prev_stone[0] or (stone[0] == prev_stone[0] and stone[1] > prev_stone[1]):
            stones_with_remaining_uses.append(stone)
        else:
            stones_used.add(stone)

    prev_stone = stones[-1]

    if not stones:
        return n

    num_able_to_kill = 0
    num_junk_monsters = 0

    while num_able_to_kill < k and num_able_to_kill < n:
        collected_monsters = []

        for monster_ind, monster_pos in enumerate(monster_positions):
            if monster_pos[0] >= prev_stone[0] and monster_pos[1] >= prev_stone[1]:
                collected_monsters.append(monster_ind)

                for stone in stones_used:
                    if any(min(prev_stone) <= other <= max(stone) for other in monster_positions):
                        num_able_to_kill += 1

                # If there’s any monster still uncollected, this means the last stone
                # can’t hit a new monster.
                if collected_monsters:
                    break

        num_junk_monsters += len(collected_monsters)
        prev_stone = collected_monsters[-1]

    stones_used = {t: [monster for monster in collected_monsters if monster >= t]
                   for monster, t in enumerate(monster_positions)}

    missing_monsters = [m for m in怪物_positions if m not in collected_monsters]

    return n - (num_junk_monsters, missing_monsters, stones_used)
