from typing import List

def minimumSwapsToPalindrome(strings: List[str]) -> int:
    if len(strings) == 0:
        return -1

    n = len(strings)
    strings = [list(s) for s in strings]
    for i in range(n-1):
        ai = strings[i]
        j = len(ai) - 1
        while j >= 0:
            if ai[j] == ai[0]:
                break
            j -= 1
        while j >= 0:
            strings[i][j], strings[i+1][j] = strings[i+1][j], strings[i][j]
            j -= 1

    needs = []
    for i in range(n):
        for j in range(len(strings[i])):
            if strings[i][j] != strings[i+1][j]:
                needs.append((i, j))

    def checkPalindrome(i, j):
        if i < 0 or j < 0:
            return False
        while i >= 0 and j < len(strings[0]) and strings[i][j] == strings[i][0][j]:
            i -= 1
            j += 1
        return True

    if all(checkPalindrome(i, j) for i, j in needs):
        return -1

    for i, j in reversed(needs):
        if checkPalindrome(i, j):
            break

        li, lj = strings[i]
        j = li[j]
        li[j] = li[-1]
        li[-1] = j
        li = li[:-1]

    j = 0
    min_swaps = 0
    for i in range(n):
        if len(strings[i]) % 2 == 1 or strings[i][0] != strings[i][-1]:
            return -1
        if not checkPalindrome(i, j):
            strings[i] = [string[::-1] for string in strings[i]]
            min_swaps += (len(strings[i]) - 1) // 2

    for i in range(n-1):
        for j in range(len(strings[i])):
            if j + 1 < len(strings[i+1]) and strings[i][j] != strings[i+1][j + 1]:
                return -1

    return len(strings) // 2 - 1

