    result = 0
    left += 1
    right += 1
    while left <= right:
        if left % 2 == 0:
            result += segment_tree[left]
            left += 1
        if right % 2 == 1:
            result += segment_tree[right]
            right -= 1
        left //= 2
        right //= 2
    return result

