from collections import defaultdict

def max_visits(n, k, parent):
    tree = defaultdict(list)
    for i in range(1, n):
        p = parent[i]
        tree[p].append(i)

    max_visits = [0] * n
    max_visits[0] = n - 1  # The tree has n-1 edges

    for level in range(1, n):
        max_visits[level] = n - (2 * (k + 1) * level // (level + 1)) - 1

    for i in range(2, n):
        p = parent[i]
        children = i
        while children in tree[p]:
            children -= 1
        for s in tree[i]:
            if s in tree[p] or children < s:
                continue
            for c in tree[s]:
                if c in tree[p]:
                    max_visits[i] = max(max_visits[i], max_visits[s] + 1)

    return max_visits[n-1]

# Example usage
